export function generateStaticParams(){return Object.keys(records).map(id=>({id}))}
export async function generateMetadata({params}:{params:Promise<{id:string}>}):Promise<Metadata>{const {id}=await params;const r=records[id];if(!r)return {title:'Build record not found',robots:{index:false,follow:false}};const title=`Build ${id} public record: ${r.title}`;const description=`Public record for Build ${id}, ${r.title}: making, reusable method, supporting evidence, source locators, and claim limits.`;return {title,description,alternates:{canonical:`/100-builds/${id}/record`},robots:{index:true,follow:true},openGraph:{title,description,type:'article'},twitter:{card:'summary',title,description}}}
export default async function RecordPage({params}:{params:Promise<{id:string}>}){const {id}=await params;const r=records[id];if(!r)notFound();return <main className={s.page}><header className={s.mast}><Link href={`/100-builds/${id}`}>← BUILD {id}</Link><span>PUBLIC BUILD RECORD</span></header>{id==='001'&&<DossierNav/>}<section className={s.hero}><span>MAKING · METHOD · EVIDENCE · LIMITS</span><h1>{r.title}</h1><p>This is the public record behind the artifact: what changed, what another person can reuse, what supports the system, and what the build is not entitled to claim.</p></section><section className={s.cards}><article><b>MAKING</b><h2>What changed</h2>{r.making.map(x=><p key={x}>{x}</p>)}</article><article><b>METHOD</b><h2>What travels</h2>{r.method.map(x=><p key={x}>{x}</p>)}</article><article><b>EVIDENCE</b><h2>What supports it</h2>{r.evidence.map(x=><p key={x}>{x}</p>)}</article><article><b>LIMITS</b><h2>What it cannot claim</h2>{r.limits.map(x=><p key={x}>{x}</p>)}</article></section>{r.sources&&r.sources.length>0&&<section className={s.takeaway} aria-label="External source locators"><h2>External source locators</h2>{r.sources.map(source=><p key={source.url}><a href={source.url} rel="noreferrer">{source.label} →</a><br/><b>Exact locator:</b> {source.locator}. <b>Scope limit:</b> {source.scope}</p>)}</section>}{id==='001'&&<section className={s.takeaway}><Link href="/100-builds/001/evidence">Open the full claim-to-source evidence map →</Link></section>}</main>}
